span.tpi-ql--table-link,
a.tpi-ql--table-link{
    width: fit-content;
    position: relative;
    transition: color 90ms ease-in-out;
    z-index: 1;
    display: flex;
    gap: .5ch;
    &:hover{
        color: #fff;
    }
    &::before {
        content: '';
        display: flex;
        position: absolute;
        left: -2px;
        top: 0;
        width: calc(100% + 6px);
        height: 100%;
        background: currentColor;
        z-index: -1;
        border-radius: 8px;
        box-shadow: 0px 0px 0px 4px;
        color: #5d5dff;
        padding: 0px 2px;
        transition: 50ms ease-in-out;
        transform: scale(0);
    }
    &:focus-visible{
        color: #fff;
        outline: none;
    }

    &:hover::before,
    &:focus-visible::before{
        transform: scale(1);
        transition: 200ms cubic-bezier(.17,.73,0,1.32);
    }
    i{
        width: 16px;
        height: 16px;
    }
    i svg{
        width: 100%;
        height: 100%;
        fill: currentColor;
    }
}

